SELECT * FROM (SELECT YEAR(event_time) AS event_year, CASE WHEN duration_sec >= 446 THEN 'high' WHEN duration_sec >= 235 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, COUNT(DISTINCT duration_sec) AS unique_sessions FROM web_events GROUP BY YEAR(event_time), CASE WHEN duration_sec >= 446 THEN 'high' WHEN duration_sec >= 235 THEN 'mid' ELSE 'low' END) AS agg WHERE unique_sessions < 4;
